import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Format cents as euros with 2 decimals.
 * @param {number} cents - amount in cents
 * @returns {string} - formatted amount (e.g., "1234.50")
 */
function formatEuro(cents) {
  const euros = cents / 100;
  return euros.toFixed(2);
}

/**
 * Escape a CSV field (add quotes if needed, escape internal quotes).
 * @param {string} field - the field value
 * @returns {string} - the escaped field
 */
function escapeCsvField(field) {
  if (field.includes(',') || field.includes('"')) {
    return `"${field.replace(/"/g, '""')}"`;
  }
  return field;
}

/**
 * Export invoices as CSV.
 * @param {Array} invoices - invoices to export
 * @returns {string} - CSV data with header and invoice lines
 */
export function exportCsv(invoices) {
  const header = 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n';

  const lines = invoices.map((inv) => {
    const customerResult = getCustomer(inv.customerId);
    const customerName = customerResult.ok ? customerResult.value.name : '';

    const totals = invoiceTotals(inv);
    const due = balanceDue(inv);

    const fields = [
      inv.number || 'DRAFT',
      customerName,
      inv.issueDate,
      inv.dueDate || '',
      inv.status,
      formatEuro(totals.subtotal),
      formatEuro(totals.discount),
      formatEuro(totals.vat),
      formatEuro(totals.total),
      formatEuro(due),
    ];

    return fields.map(escapeCsvField).join(',');
  });

  return header + lines.join('\n') + (lines.length > 0 ? '\n' : '');
}

